static Compiled compile(String sql, Map<String,Object> named) {
    if (named == null || named.isEmpty())
        throw new IllegalArgumentException("named params required");
    StringBuilder out = new StringBuilder(sql.length());
    List<Object> ordered = new ArrayList<>();
    boolean inS=false, inD=false, inLine=false, inBlock=false;
    for (int i=0; i<sql.length(); i++) {
        char c=sql.charAt(i), n=(i+1<sql.length()?sql.charAt(i+1):'\0');
        if (!inS && !inD) {
            if (!inBlock && c=='-'&&n=='-') {
                inLine=true;
                out.append(c);
                continue;
            }
            if (inLine && c=='\n') {
                inLine=false;
                out.append(c);
                continue;
            }
            if (!inLine && !inBlock && c=='/'&&n=='*') {
                inBlock=true;
                out.append("/*");
                i++;
                continue;
            }
            if (inBlock && c=='*'&&n=='/') {
                inBlock=false;
                out.append("*/");
                i++;
                continue;
            }
        }
        if (inLine || inBlock) {
            out.append(c);
            continue;
        }
        if (!inD && c=='\'') {
            inS=!inS;
            out.append(c);
            continue;
        }
        if (!inS && c=='"') {
            inD=!inD;
            out.append(c);
            continue;
        }
        if (inS || inD) {
            out.append(c);
            continue;
        }
        if (c==':' && Character.isJavaIdentifierStart(n)) {
            int j=i+1;
            while (j<sql.length()) {
                char cj=sql.charAt(j);
                if (!(Character.isJavaIdentifierPart(cj) || cj=='$' || cj=='_')) break;
                j++;
            }
            String name = sql.substring(i+1, j);
            if (!named.containsKey(name))
                throw new IllegalArgumentException("missing named param: " + name);
            out.append('?');
            ordered.add(named.get(name));
            i=j-1;
            continue;
        }
        out.append(c);
    }
    return new Compiled(out.toString(), ordered);
}

