    if (m_lastChunk == 0 && m_innerFSB != null) {
        m_innerFSB.setLength(l, this);
    } else {
        m_firstFree = l & m_chunkMask;
        if(m_firstFree==0 && m_lastChunk>0) {
            --m_lastChunk;
            m_firstFree=m_chunkSize;
        }
    }
