        break;
    case OpCodes.FROM_FOLLOWING_SIBLINGS :
        prevIsOneStepDown = false;
        ai = new AxesWalker(lpi, Axis.FOLLOWINGSIBLING);
        break;
    case OpCodes.FROM_PRECEDING :
        prevIsOneStepDown = false;
        ai = new ReverseAxesWalker(lpi, Axis.PRECEDING);
