public boolean startsWith(XMLString prefix, int toffset)
  {

    int to = toffset;
    int tlim = this.length();
    int po = 0;
    int pc = prefix.length();

    // Note: toffset might be near -1>>>1.
    if ((toffset < 0) || (toffset > tlim - pc))
    {
      return false;
    }

    while (--pc >= 0)
    {
      if (this.charAt(to) != prefix.charAt(po))
      {
        return false;
      }

      to++;
      po++;
    }

    return true;
  }

code_formatted:
public boolean startsWith(XMLString prefix, int toffset) {
    int to = toffset;
    int tlim = this.length();
    int po = 0;
    int pc = prefix.length();
    if ((toffset < 0) || (toffset > tlim - pc)) {
        return false;
    }
    while (--pc >= 0) {
        if (this.charAt(to) != prefix.charAt(po)) {
            return false;
        }
        to++;
        po++;
    }
    return true;
}

