    int i = 0;
    int j = 0;
    while (n-- != 0) {
        char c1 = this.charAt(i);
        char c2 = xstr.charAt(j);
        if (c1 != c2) {
            return c1 - c2;
        }
        i++;
        j++;
    }
    return len1 - len2;
}

