private static MemorySegment wrapByteBuffer(ByteBuffer buffer) {
        if (buffer.isDirect()) {
            return MemorySegment.wrapOffHeapMemory(buffer);
        } else {
            byte[] bytes = new byte[buffer.remaining()];
            int pos = buffer.position();
            buffer.get(bytes);
            buffer.position(pos);
            return MemorySegment.wrap(bytes);
        }
    }

