public static Point2D pointAtT (CubicCurve2D c,
                                    double t)
    {
        final double u = 1 - t;

        double x = (c.getX1() * u * u * u) + (3 * c.getCtrlX1() * t * u * u) + (3 * c.getCtrlX2()
                * t * t * u) + (c.getX2() * t * t * t);

        double y = (c.getY1() * u * u * u) + (3 * c.getCtrlY1() * t * u * u) + (3 * c.getCtrlY2()
                * t * t * u) + (c.getY2() * t * t * t);

        return new Point2D.Double(x, y);
    }

