static Rgb indexedToRgb(int index) {
    if (index < 16) {
        return ansiToRgb(AnsiColor.values()[index]);
    } else if (index < 232) {
        int i = index - 16;
        int r = (i / 36) % 6;
        int g = (i / 6) % 6;
        int b = i % 6;
        return new Rgb(
                   r == 0 ? 0 : 55 + r * 40,
                   g == 0 ? 0 : 55 + g * 40,
                   b == 0 ? 0 : 55 + b * 40
               );
    } else {
        int gray = 8 + (index - 232) * 10;
        return new Rgb(gray, gray, gray);
    }
}

